def lru_cache(maxsize=128, typed=False):
    cache = {}
    def _wrap(func):
        nonlocal cache
        @functools.wraps(func)
        def _(*args, **kwargs):
            key = args + tuple(sorted(kwargs.items()))
            if not typed:
                key = (id(key),) + key
            if key in cache:
                result = cache.pop(key)
                cache[key] = result
            else:
                result = func(*args, **kwargs)
                if len(cache) >= maxsize:
                    cache.popitem(last=False)
                cache[key] = result
            return result
        return _
    return _wrap

