def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    import subprocess
    import sys
    import os

    # Ensure that commands is a list even if only one command is provided
    if not isinstance(commands, list):
        commands = [commands]

    # Ensure that args is a list even if no args are provided
    if not isinstance(args, list):
        args = []

    # Define the lambda function to handle the subprocess output
    def handle_output(proc, para):
        if para.verbose:
            if para.hide_stderr:
                for line in proc.stdout:
                    sys.stdout.write(line)
            else:
                for line in proc.stdout + proc.stderr:
                    sys.stdout.write(line)

    # Create a dictionary with subprocess output handlers
    output_handlers = {
        "stdout": handle_output,
        "stderr": handle_output
    }

    # Create a subprocess object for each command
    procs = []
    for command in commands:
        proc = subprocess.Popen(command, cwd=cwd, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        procs.append(proc)

    # Loop through all subprocess objects and run their command
    for proc in procs:
        proc.run()

    # Check if any subprocess returned with an error code
    for proc in procs:
        if proc.returncode != 0:
            raise subprocess.CalledProcessError(proc.returncode, command, proc.stdout, proc.stderr)

    # Return the stdout and stderr contents of all subprocesses
    return {proc.stdout for proc in procs}, {proc.stderr for proc in procs}

