        if os.path.exists(os.path.join(path, "0=*")):
            if os.path.isfile(os.path.join(path, "descriptor.json")):
                return "root"
            elif os.path.isfile(os.path.join(path, "inventory.json")):
                return "object"
            else:
                return "unknown"
        else:
            return "file"
    else:
        return "unknown"

