def deep_merge_nodes(nodes):
    result = []
    seen_keys = set()
    for node in nodes:
        key, value = node
        if isinstance(value, ruamel.yaml.nodes.ScalarNode):
            if key.value not in seen_keys:
                result.append(node)
                seen_keys.add(key.value)
        elif isinstance(value, ruamel.yaml.nodes.MappingNode):
            for subkey, subvalue in value.value:
                if subkey.value in seen_keys:
                    result[-1][1].value.append((subkey, subvalue))
                else:
                    result.append((key, ruamel.yaml.nodes.MappingNode(tag='tag:yaml.org,2002:map', value=[(subkey, subvalue)])))
                    seen_keys.add(subkey.value)
        else:
            result.append(node)
    return result

