def size_to_bytes(size: str) -> int:
    matches = re.findall(r'(\d+)([KMGTP])', size.upper())
    if len(matches) == 0:
        return int(size)
    count, unit = matches[0]
    if unit == 'K':
        return int(count) * 1000
    if unit == 'M':
        return int(count) * 1000 * 1000
    if unit == 'G':
        return int(count) * 1000 * 1000 * 1000
    if unit == 'T':
        return int(count) * 1000 * 1000 * 1000 * 1000
    if unit == 'P':
        return int(count) * 1000 * 1000 * 1000 * 1000 * 1000

