def split(s, platform="this"):
    platform_regex = {
        "this": re.compile(r"(?:\G(?!\A)|^\s*)([^\s])[^\s]*?(?P<token>(\\"|\\\')(?:\\\1|[^\1])|\"(?:\\\"|[^\"])*?\"|\'(?:\\\'|[^\'])\'|\S+)[^\n\s]*"),
        "1": re.compile(r"(?:\G(?!\A)|^\s*)(?:([^\s])[^\s]*?(?P<token>(\\"|\\\')(?:\\\1|[^\1])|\"(?:\\\\\"|[^\"])*?\"|\'(?:\\\\\'|[^\'])+\'|\S+)[^\n\s]*|(\\$\([^\)]*\)|\$\{?[a-zA-Z0-9._ -]+\}?))[^\n\s]*"),
        "0": re.compile(r"(?:\G(?!\A)|^\s*)(?:([^\s])[^\s]*?(?P<token>(\\"|\\\')(?:\\\1|[^\1])|\"(?:\\\\\"|[^\"])*?\"|\'(?:\\\\\'|[^\'])+\'|\S+)[^\n\s]*|(\\$\([^\)]*\)|\$\{?[a-zA-Z0-9._ -]+\}?))[^\n\s]*")
    }

    def _windows_split(s):
        position = 0
        parts = []
        while position < len(s):
            match = platform_regex["0"].match(s[position:])
            if match is None:
                break
            if match.group("token") is not None:
                parts.append(match.group("token"))
            position += len(match.group(0))
        return parts

    def _posix_split(s):
        position = 0
        parts = []
        while position < len(s):
            match = platform_regex["1"].match(s[position:])
            if match is None:
                break
            if match.group("token") is not None:
                parts.append(match.group("token"))
            position += len(match.group(0))
        return parts

    if platform in {"1", "0"}:
        return _windows_split(s) if platform == "1" else _posix_split(s)
    else:
        return _windows_split(s) if platform == "this" and os.name == "nt" else _posix_split(s)

def add_ignored(ignored):
    """Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma."""
    ignored_files = subprocess.check_output(["git", "ls-files", "-i", "--exclude-per-directory", "--others"]).decode("utf-8")
