def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None
    parts = frequency.lower().split()
    if not parts:
        raise ValueError("Invalid frequency format")
    num = parts[0]
    unit = parts[1]
    try:
        num = int(num)
    except ValueError:
        raise ValueError("Invalid frequency format")
    if unit == "weeks":
        return datetime.timedelta(weeks=num)
    elif unit == "days":
        return datetime.timedelta(days=num)
    elif unit == "hours":
        return datetime.timedelta(hours=num)
    elif unit == "minutes":
        return datetime.timedelta(minutes=num)
    elif unit == "seconds":
        return datetime.timedelta(seconds=num)
    else:
        raise ValueError("Invalid frequency unit")

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    if matcher.group(1) is not None and os.environ.get(matcher.group(1)):
        return os.environ.get(matcher.group(1))
    elif matcher.group(2) is not None:
        return matcher.group(2)
    else:
        raise ValueError("Undefined environment variable")

def remove_ending_os_sep(input_list):
