def scale(self, other=None, recompute=False):
    if other is None:
        if self.scale is None or recompute:
            self.scale = sum(self.values)
        return self.scale
    if not isinstance(other, float):
        raise ValueError("Invalid input type for scale")
    if self.scale is None or recompute:
        self.scale = sum(self.values)
    scaled_values = [value * other for value in self.values]
    self.values = scaled_values
    self.scale = other * self.scale
    return self

def scale(self, other=None):
    if other is None:
        return self.scale
    else:
        # Check that the graph has a scale
        if self.scale == 0:
            raise LenaValueError("Graph has unknown or zero scale")

        # Rescale the graph's fields
        for field in self.fields:
            setattr(self, field, getattr(self, field) * other)

        # Set the new scale
        self.scale = other

