def isoparse(dt_str):
    # Parse an ISO-8601 datetime string into a datetime.datetime object
    # Note that this method conforms to the specification provided in the docstring

    # Initialize a dictionary to hold the parsed date and time components
    par = {}

    # Split the datetime string into a date and a time portion
    dt, t = dt_str.split('T')

    # Parse the date portion
    if '-' in dt:
        par['Y'], par['m'], par['d'] = dt.split('-')
    elif '+' in dt:
        par['Y'], par['m'], par['d'] = dt.split('+')
    else:
        raise ValueError("Incorrect date format")

    # Parse the time portion
    if ':' in t:
        par['H'], par['M'], par['S'] = t.split(':')
    else:
        par['H'], par['M'], par['S'] = t.split('-')

    # Convert the date and time components into a datetime.datetime object
    dt = datetime.datetime(**par)

    return dt

