def identify_request(request: RequestType):
    public_message_payload = request.get_public_message()
    if public_message_payload is not None:
        return RequestType.PUBLIC_MESSAGE

    private_message_payload = request.get_private_message()
    if private_message_payload is not None:
        return RequestType.PRIVATE_MESSAGE

    legacy_payload = request.get_legacy_payload()
    if legacy_payload is not None:
        return RequestType.LEGACY

    raise Exception("Unable to identify type of request")

